struct DownloadInfo {
 std::shared_ptr<std::ifstream> file;std::string name,type;long long total=0,first=0,length=0;int status=200;
};
DownloadInfo prepare_download(const Req&r){
 URL url(std::string(r.target()));DB db;auto bearer=std::string(r[http::field::authorization]);auto uid=auth(db,bearer.rfind("Bearer ",0)==0?bearer.substr(7):"");auto rows=db.sql("SELECT * FROM files WHERE id="+db.q(url.args["id"]));if(rows.empty())throw Error(404,"文件不存在");auto row=rows[0];member(db,uid,number(row["conversation_id"]));std::string id=row["id"];if(!is_hex(id,32))throw Error(404,"无效文件标识");DownloadInfo info;info.name=row["name"];info.type=media_type(info.name);info.total=number(row["size"]);info.length=info.total;info.file=std::make_shared<std::ifstream>(std::filesystem::path(env("FILE_DIR","/data/files"))/id,std::ios::binary);if(!*info.file)throw Error(404,"文件内容不存在");info.file->seekg(0,std::ios::end);if(info.file->tellg()!=static_cast<std::streamoff>(info.total))throw Error(500,"文件大小异常，请联系发送者");auto range=std::string(r[http::field::range]);if(!range.empty()){
  try{if(range.rfind("bytes=",0)!=0||range.find(',')!=range.npos)throw Error(416,"无效范围");auto value=range.substr(6);auto dash=value.find('-');if(dash==value.npos)throw Error(416,"无效范围");auto left=value.substr(0,dash),right=value.substr(dash+1);long long last=info.total-1;if(left.empty()){auto suffix=number(right);if(suffix==0)throw Error(416,"无效范围");info.first=std::max(0LL,info.total-suffix);}else{info.first=number(left);if(!right.empty())last=std::min(last,number(right));}if(info.first>=info.total||last<info.first)throw Error(416,"无效范围");info.length=last-info.first+1;info.status=206;}catch(...){info.status=416;info.length=0;}
 }info.file->seekg(info.first);return info;
}
struct DownloadSession:std::enable_shared_from_this<DownloadSession>{
 beast::tcp_stream stream;DownloadInfo info;http::response<http::empty_body>response;std::shared_ptr<http::response_serializer<http::empty_body>>serializer;std::vector<char>buffer;long long remaining;bool stopped=false;
 DownloadSession(beast::tcp_stream s,DownloadInfo value):stream(std::move(s)),info(std::move(value)),response(static_cast<http::status>(info.status),11),buffer(128*1024),remaining(info.length){}
 ~DownloadSession(){--connections;}
 void close(){if(stopped)return;stopped=true;beast::error_code ec;stream.socket().shutdown(tcp::socket::shutdown_both,ec);stream.socket().close(ec);}
 void start(){response.set(http::field::content_type,info.type);response.set(http::field::accept_ranges,"bytes");response.set(http::field::content_disposition,"attachment");response.set(http::field::cache_control,"no-store");response.set("X-Content-Type-Options","nosniff");response.content_length(static_cast<uint64_t>(info.length));response.keep_alive(false);if(info.status==206)response.set(http::field::content_range,"bytes "+std::to_string(info.first)+"-"+std::to_string(info.first+info.length-1)+"/"+std::to_string(info.total));if(info.status==416)response.set(http::field::content_range,"bytes */"+std::to_string(info.total));serializer=std::make_shared<http::response_serializer<http::empty_body>>(response);stream.expires_after(std::chrono::seconds(30));http::async_write_header(stream,*serializer,[self=shared_from_this()](beast::error_code ec,size_t){if(ec){self->close();return;}self->next();});}
 void next(){if(stopped)return;if(!remaining){close();return;}auto self=shared_from_this();if(!work([self]{auto length=static_cast<size_t>(std::min<long long>(self->remaining,self->buffer.size()));self->info.file->read(self->buffer.data(),static_cast<std::streamsize>(length));auto read=self->info.file->gcount();net::post(self->stream.get_executor(),[self,length,read]{if(self->stopped)return;if(read!=static_cast<std::streamsize>(length)){self->close();return;}self->stream.expires_after(std::chrono::seconds(60));net::async_write(self->stream,net::buffer(self->buffer.data(),length),[self,length](beast::error_code ec,size_t){if(ec){self->close();return;}self->remaining-=length;self->next();});});})){close();}}
};
